const mails = await api.get("/mails", {});
const customers = await api.get("/customers", { tier: "gold" });
const mArr = Array.isArray(mails) ? mails : (mails.items || mails.data || []);
const cArr = Array.isArray(customers) ? customers : (customers.items || customers.data || []);
console.log("mails type:", Array.isArray(mails) ? "array" : Object.keys(mails));
console.log("mail keys:", mArr[0] ? Object.keys(mArr[0]) : "none");
console.log("customers type:", Array.isArray(customers) ? "array" : Object.keys(customers));
console.log("customer keys:", cArr[0] ? Object.keys(cArr[0]) : "none");
console.log("mail count:", mArr.length, "gold count:", cArr.length);

const mails = await api.get("/mails", {});
const customers = await api.get("/customers", { tier: "gold" });
const labels = [...new Set(mails.items.map(m => m.label))];
console.log("labels:", labels);
const gold = customers.items.filter(c => c.tier === "gold");
const goldIds = new Set(gold.map(c => c.id));
const refundMails = mails.items.filter(m => /환불|refund/i.test(m.label || "") || /환불/.test(m.subject || ""));
const matched = refundMails.filter(m => goldIds.has(m.customer_id)).map(m => ({ customer_id: m.customer_id, mail_label: m.label, subject: m.subject }));
const names = gold.filter(c => matched.some(x => x.customer_id === c.id)).map(c => c.name);
console.log("refund mails:", refundMails.length, "matched:", matched.length);
return { names, matched };

